CREATE   VIEW [GotoWebinar].[vwRegistrantDetails]
AS
SELECT
	CAST(reg.[Webinarkey] AS NVARCHAR(20)) + '_' + CAST(reg.[registrantkey] AS NVARCHAR(20)) AS [RegistrationKey]
	,reg.[registrantKey]
	,reg.[WebinarKey]
	,reg.[firstName] AS [First Name]
	,reg.[lastName] As [Last Name]
	,reg.[email]
	,CAST(reg.[registrationDate] AS DATE) AS [Registration Date]
	,reg.[status] As [Registration Status]
	,reg.[timeZone] AS [Registration Timezone]
	,reg.[jobTitle]
	,reg.[country]
	,reg.[organization]
	,reg.[source]
	,reg.[type] AS [Registrant Type]
	,reg.[unsubscribed]
	,reg.[employeeCount]
	,reg.[phone]
	,reg.[zipCode]
	,reg.[industry]
	,reg.[implementationTimeFrame]
	,reg.[numberOfEmployees]
FROM [GoToWebinar].[tblRegistrantDetails] reg
